// JWT doğrulama — GET /persona
const crypto = require('crypto');

function b64uDecode(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return Buffer.from(s, 'base64').toString('utf8');
}

const authHeader = $input.first().json.headers?.authorization ?? '';
const token = authHeader.replace(/^Bearer\s+/i, '');
if (!token) throw new Error('401: Token eksik');

const parts = token.split('.');
if (parts.length !== 3) throw new Error('401: Geçersiz token');

const [header, payload, sig] = parts;
const expected = crypto
  .createHmac('sha256', $env.JWT_SECRET)
  .update(`${header}.${payload}`)
  .digest('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');

const __sigBuf = Buffer.from(sig);
const __expBuf = Buffer.from(expected);
if (__sigBuf.length !== __expBuf.length || !crypto.timingSafeEqual(__sigBuf, __expBuf)) throw new Error('401: Geçersiz imza');

const claims = JSON.parse(b64uDecode(payload));
if (claims.exp < Math.floor(Date.now() / 1000)) throw new Error('401: Token süresi dolmuş');

// Query params'tan client_id al
const clientId = $input.first().json.query?.client_id ?? '';
if (!clientId) throw new Error('400: client_id zorunlu');
// SQL'e string interpolation ile girdiği için format guard'ı şart
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!UUID_RE.test(clientId)) throw new Error('400: client_id geçersiz format');

return [{ json: { client_id: clientId, _sub: claims.sub } }];

// JWT doğrulama — POST /persona/upsert
const crypto = require('crypto');

function b64uDecode(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return Buffer.from(s, 'base64').toString('utf8');
}

const item = $input.first().json;
const authHeader = item.headers?.authorization ?? '';
const token = authHeader.replace(/^Bearer\s+/i, '');
if (!token) throw new Error('401: Token eksik');

const parts = token.split('.');
if (parts.length !== 3) throw new Error('401: Geçersiz token');

const [header, payload, sig] = parts;
const expected = crypto
  .createHmac('sha256', $env.JWT_SECRET)
  .update(`${header}.${payload}`)
  .digest('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');

const __sigBuf = Buffer.from(sig);
const __expBuf = Buffer.from(expected);
if (__sigBuf.length !== __expBuf.length || !crypto.timingSafeEqual(__sigBuf, __expBuf)) throw new Error('401: Geçersiz imza');

const claims = JSON.parse(b64uDecode(payload));
if (claims.exp < Math.floor(Date.now() / 1000)) throw new Error('401: Token süresi dolmuş');

const body = item.body ?? {};
if (!body.client_id) throw new Error('400: client_id zorunlu');
// SQL'e string interpolation ile girdiği için format guard'ı şart
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!UUID_RE.test(body.client_id)) throw new Error('400: client_id geçersiz format');
if (!body.identity || !String(body.identity).trim()) throw new Error('400: identity zorunlu');

return [{ json: { ...body, _sub: claims.sub } }];

// Persona upsert SQL oluştur
const esc = (s) => s == null ? 'NULL' : `'${String(s).replace(/'/g, "''")}'`;
const escArr = (arr) => arr && arr.length ? `ARRAY[${arr.map(esc).join(',')}]::text[]` : `'{}'::text[]`;
const escJson = (v) => v == null ? "'[]'::jsonb" : `'${JSON.stringify(v).replace(/'/g, "''")}' ::jsonb`;

// Sayılar SQL'e doğrudan interpolate ediliyor — Number değilse injection riski
const num = (v, def, min, max) => {
  const n = Number(v);
  return Number.isFinite(n) ? Math.min(max, Math.max(min, Math.round(n))) : def;
};
const arr = (v) => Array.isArray(v) ? v : [];

const d = $input.first().json;
const voiceExamples = arr(d.voice_examples).map((ex) => ({
  tone: String(ex?.tone ?? 'sert'),
  example: String(ex?.example ?? ''),
}));

const sql = `INSERT INTO personas
  (client_id, identity, ideology, themes, banned_words, banned_topics,
   address_form, voice_examples, reference_prompt, max_chars, daily_tweet_count)
VALUES
  (${esc(d.client_id)}, ${esc(d.identity)}, ${esc(d.ideology ?? 'conservative')},
   ${escArr(arr(d.themes))}, ${escArr(arr(d.banned_words))}, ${escArr(arr(d.banned_topics))},
   ${esc(d.address_form)}, ${escJson(voiceExamples)}, ${esc(d.reference_prompt)},
   ${num(d.max_chars, 280, 1, 280)}, ${num(d.daily_tweet_count, 3, 1, 17)})
ON CONFLICT (client_id) DO UPDATE SET
  identity          = EXCLUDED.identity,
  ideology          = EXCLUDED.ideology,
  themes            = EXCLUDED.themes,
  banned_words      = EXCLUDED.banned_words,
  banned_topics     = EXCLUDED.banned_topics,
  address_form      = EXCLUDED.address_form,
  voice_examples    = EXCLUDED.voice_examples,
  reference_prompt  = EXCLUDED.reference_prompt,
  max_chars         = EXCLUDED.max_chars,
  daily_tweet_count = EXCLUDED.daily_tweet_count,
  updated_at        = now()
RETURNING id, client_id, updated_at;`;

return [{ json: { sql } }];
